flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.45; newrank=true;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", penwidth=2];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  TASK [label="A complex task", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  Q [label="⭐ Are the steps known\nin advance?", shape=diamond, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  LOCAL [label="⭐ Per-file passes\n(local analysis, one file each)", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  INTEG [label="⭐ Cross-file integration pass\n(over the per-file summaries)", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  MAP [label="⭐ Map the structure", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  PRIO [label="⭐ Prioritise high-impact areas", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  DO [label="Work the next subtask", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  ADAPT [label="⭐ Discovered a dependency?\n→ add a subtask, retry", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  DONE [label="Complete result", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  ONEPASS [label="✗ one pass over\nevery file", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOINTEG [label="✗ no integration pass", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  PICKY [label="✗ adaptive plan for a\npredictable review", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  FIXEDPLAN [label="✗ fixed plan for an\nopen-ended task", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOADAPT [label="✗ plan never adapts", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  TASK -> Q;
  Q -> LOCAL [label="yes: predictable review"]; LOCAL -> INTEG; INTEG -> DONE;
  Q -> MAP [label="no: open-ended"]; MAP -> PRIO; PRIO -> DO; DO -> ADAPT; ADAPT -> DO [label="new subtask", constraint=false];
  ADAPT -> DONE;
  { rank=same; LOCAL; } { rank=same; MAP; } LOCAL -> MAP [style=invis];
  { rank=same; ONEPASS; NOINTEG; } { rank=same; PICKY; FIXEDPLAN; } { rank=same; NOADAPT; } ONEPASS -> PICKY [style=invis]; NOINTEG -> FIXEDPLAN [style=invis]; PICKY -> NOADAPT [style=invis];
  DONE -> ONEPASS [style=invis];
  KEY [shape=plain, label=<<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="3" CELLPADDING="3"><TR><TD COLSPAN="2" BORDER="0" ALIGN="LEFT"><FONT POINT-SIZE="18"><B>Key</B></FONT></TD></TR><TR><TD BGCOLOR="#EDE9FE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">choosing the pattern</FONT></TD></TR><TR><TD BGCOLOR="#DBEAFE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">prompt chaining (fixed steps)</FONT></TD></TR><TR><TD BGCOLOR="#FEF3C7" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">dynamic decomposition (adapts)</FONT></TD></TR><TR><TD BGCOLOR="#D1FAE5" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">result</FONT></TD></TR><TR><TD BGCOLOR="#FFFFFF" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">bug (an exam distractor)</FONT></TD></TR><TR><TD WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"><FONT POINT-SIZE="16">⭐</FONT></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">named by the exam guide (TS 1.6, p.8)</FONT></TD></TR></TABLE>>];
  NOINTEG -> KEY [style=invis];
}

decisionDot:
digraph D {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.4;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", fillcolor="#F3F4F6", color="#9CA3AF", penwidth=1.5];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  Q1 [shape=diamond, label="Are the steps known in advance?"];
  Q2 [shape=diamond, label="Does it span many files?"];
  CH [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="Chain: per-file passes\n→ cross-file integration pass"];
  ONE [shape=box, label="One pass is fine"];
  DY [shape=box, fillcolor="#FEF3C7", color="#D97706", label="Dynamic: map → prioritise →\nadapt as dependencies appear"];
  Q1 -> Q2 [label="yes"]; Q1 -> DY [label="no"]; Q2 -> CH [label="yes"]; Q2 -> ONE [label="no"];
}
